    Картинка1 = "https://releases.openintegrations.dev/test_data/picture.jpg";  // URL, Двоичные или Путь к файлу
    Картинка2 = "https://releases.openintegrations.dev/test_data/picture2.jpg"; // URL, Двоичные или Путь к файлу
