    СтруктураДокумента.Вставить("nullField");

    МассивДокументов.Добавить(СтруктураДокумента);

    // С явным приведением типов
    СтруктураДокумента = Новый Структура;

    RegExp = Новый Структура("pattern,options", "[a-z]+@[a-z]+\.[a-z]+", "i");
