            Если ПоследнееСообщение["result"] Тогда
                // Очередное сообщение
                Проверка = ПоследнееСообщение;
            Иначе
                // Сообщений больше нет
                Прервать;
            КонецЕсли;

        КонецЦикла;

    Иначе
        Результат = Соединение;
        Проверка  = Соединение;
    КонецЕсли;
